examples.template:
MonarchFormField(
    label = {{label}},
    helperText = (period?.let { (start, end) -> iso.format(Date(start)) + " to " + iso.format(Date(end)) } ?: "No period") + "; at most {{maxDays}} days.",
) { controlModifier ->
    Row(
        modifier = controlModifier
            .fillMaxWidth()
            .border(1.dp, MonarchTheme.colors.borderInput, MonarchTheme.shapes.md)
            .clickable { picking = true }
            .padding(start = MonarchTheme.spacing.space3),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchText(
            text = period?.let { (start, end) -> "${format.format(Date(start))} \u2013 ${format.format(Date(end))}" } ?: "Choose dates",
            modifier = Modifier.weight(1f),
        )
        if (period != null) {
            MonarchIconButton(label = "Clear dates", onClick = { period = null; state.setSelection(null, null) }) {
                MonarchIcon(SampleIcons.Close, contentDescription = null, size = MonarchIconSize.Sm)
            }
        }
        MonarchIconButton(label = "Choose dates", onClick = { picking = true }) {
            MonarchIcon(SampleIcons.Calendar, contentDescription = null, size = MonarchIconSize.Sm)
        }
    }
}
if (picking) {
    val start = state.selectedStartDateMillis
    val end = state.selectedEndDateMillis
    DatePickerDialog(
        onDismissRequest = { picking = false },
        confirmButton = {
            MonarchButton(
                text = "Save",
                onClick = {
                    if (start != null && end != null) period = start to end
                    picking = false
                },
                variant = MonarchButtonVariant.Primary,
                enabled = start != null && end != null && (end - start) / 86_400_000L < {{maxDays}},
            )
        },
        dismissButton = {
            Row {
                Box {
                    MonarchButton(text = "Presets", onClick = { presets = true }, variant = MonarchButtonVariant.Ghost)
                    MonarchMenu(expanded = presets, onDismissRequest = { presets = false }) {
                        MonarchMenuItem(text = {{presets.0.label}}, onClick = { choose(today - ({{presets.0.lastDays}} - 1) * 86_400_000L, today) })
                        MonarchMenuItem(text = {{presets.1.label}}, onClick = { choose(today - ({{presets.1.lastDays}} - 1) * 86_400_000L, today) })
                        MonarchMenuItem(text = {{presets.2.label}}, onClick = { choose(today - ({{presets.2.lastDays}} - 1) * 86_400_000L, today) })
                        MonarchMenuItem(text = {{presets.3.label}}, onClick = { val (start, end) = month({{presets.3.months}}L); choose(start, end) })
                        MonarchMenuItem(text = {{presets.4.label}}, onClick = { val (start, end) = month({{presets.4.months}}L); choose(start, end) })
                    }
                }
                MonarchButton(text = "Cancel", onClick = { picking = false }, variant = MonarchButtonVariant.Ghost)
            }
        },
    ) {
        DateRangePicker(state = state, modifier = Modifier.weight(1f))
    }
}

examples.setupTemplate:
val today = {{today|millis}}
var period by remember { mutableStateOf<Pair<Long, Long>?>({{value.start|millis}} to {{value.end|millis}}) }
var picking by remember { mutableStateOf(false) }
var presets by remember { mutableStateOf(false) }
val state = rememberDateRangePickerState(
    initialSelectedStartDateMillis = {{value.start|millis}},
    initialSelectedEndDateMillis = {{value.end|millis}},
    selectableDates = object : SelectableDates {
        override fun isSelectableDate(utcTimeMillis: Long): Boolean = utcTimeMillis <= today
    },
)
val format = remember { DateFormat.getDateInstance(DateFormat.SHORT, Locale.forLanguageTag({{locale}})).apply { timeZone = TimeZone.getTimeZone("UTC") } }
val iso = remember { SimpleDateFormat("yyyy-MM-dd", Locale.ROOT).apply { timeZone = TimeZone.getTimeZone("UTC") } }
val choose = { start: Long, end: Long ->
    period = start to end
    state.setSelection(start, end)
    presets = false
}
fun month(offset: Long): Pair<Long, Long> {
    val first = LocalDate.ofEpochDay(today / 86_400_000L).withDayOfMonth(1).plusMonths(offset)
    return first.toEpochDay() * 86_400_000L to minOf(first.plusMonths(1).minusDays(1).toEpochDay() * 86_400_000L, today)
}

